    #[test]
    fn creature_basis_orients_forward_and_scales() {
        let pos = Vec3::new(3.0, -2.0, 5.0);
        let fwd = Vec3::new(1.0, 0.0, 0.0); // moving +X
        let size = 4.0;
        let m = creature_basis(pos, fwd, fwd, 0.0, size); // no banking
        // Local +Z (forward) maps to the velocity direction, scaled by size.
        let zc = m.transform_vector3(Vec3::Z);
        assert!((zc - fwd * size).length() < 1e-4, "forward must map to velocity·size");
        // Translation is the agent position.
        assert!((m.transform_point3(Vec3::ZERO) - pos).length() < 1e-4);
        // Basis columns stay orthogonal and uniformly scaled.
        let xc = m.transform_vector3(Vec3::X);
        let yc = m.transform_vector3(Vec3::Y);
        assert!(xc.dot(zc).abs() < 1e-3 && xc.dot(yc).abs() < 1e-3);
        assert!((xc.length() - size).abs() < 1e-3 && (yc.length() - size).abs() < 1e-3);
    }

