    // --- Acoustic-field generator (#325, Duo-Field N1) ---

    #[test]
    fn acoustic_monopole_matches_closed_form() {
        // A single +1 monopole: pressure = sin(ωt−kr)/r, velocity along +r̂ with
        // magnitude k·sin/r − near·cos/r². Point on +Y so r̂ = +Y.
        let src = acoustic_sources(AcousticKind::Monopole, 1.0);
        let (k, near, r_min, phase) = (1.3, 0.7, 0.1, 0.4);
        let r = 3.0;
        let (pres, u) = acoustic_field_pu(Vec3::new(0.0, r, 0.0), &src, k, near, r_min, phase);
        let arg = phase - k * r;
        assert!((pres - arg.sin() / r).abs() < 1e-5, "pressure closed form");
        let expect_u = k * arg.sin() / r - near * arg.cos() / (r * r);
        assert!((u.y - expect_u).abs() < 1e-5, "velocity closed form");
        assert!(u.x.abs() < 1e-6 && u.z.abs() < 1e-6, "velocity is radial (+Y)");
    }

    #[test]
    fn acoustic_dipole_has_equatorial_pressure_node_and_axial_lobe() {
        // Dipole axis = Z (±h monopoles, opposite sign). A point in the z=0 plane
        // is equidistant from both → the ± pressures cancel (the angular node).
        let src = acoustic_sources(AcousticKind::Dipole, 1.0);
        let (k, near, r_min, phase) = (1.0, 0.5, 0.05, 0.7);
        let (p_eq, _) = acoustic_field_pu(Vec3::new(4.0, 0.0, 0.0), &src, k, near, r_min, phase);
        assert!(p_eq.abs() < 1e-5, "equatorial pressure node");
        // On the axis the two contributions do NOT cancel → a lobe.
        let (p_ax, _) = acoustic_field_pu(Vec3::new(0.0, 0.0, 4.0), &src, k, near, r_min, phase);
        assert!(p_ax.abs() > 1e-3, "axial pressure lobe present");
    }

    #[test]
    fn acoustic_pressure_and_near_velocity_are_in_quadrature() {
        // At a near point, pressure ∝ sin(arg) while the 1/r² velocity term ∝
        // cos(arg): 90° out of phase. arg=0 → pressure node, velocity antinode;
        // arg=π/2 → pressure antinode.
        let src = acoustic_sources(AcousticKind::Monopole, 1.0);
        let (k, near, r_min) = (0.5, 1.0, 0.1);
        let p = Vec3::new(0.0, 0.5, 0.0);
        let r = 0.5;
        let (pr0, u0) = acoustic_field_pu(p, &src, k, near, r_min, k * r); // arg = 0
        assert!(pr0.abs() < 1e-5, "pressure node at arg=0");
        assert!(u0.length() > 1e-3, "velocity antinode at arg=0 (quadrature)");
        let (pr1, _) = acoustic_field_pu(p, &src, k, near, r_min, k * r + std::f32::consts::FRAC_PI_2);
        assert!(pr1.abs() > 1e-3, "pressure antinode at arg=π/2");
    }

    #[test]
    fn note_freq_is_equal_tempered() {
        assert!((note_freq(69.0, 0.0, 440.0) - 440.0).abs() < 1e-3, "A4 = 440");
        assert!((note_freq(81.0, 0.0, 440.0) - 880.0).abs() < 1e-2, "A5 = 880");
        assert!((note_freq(57.0, 0.0, 440.0) - 220.0).abs() < 1e-2, "A3 = 220");
        // +2 semitone bend on A4 = B4 ≈ 493.88 Hz.
        assert!((note_freq(69.0, 2.0, 440.0) - 493.883).abs() < 1e-1, "A4 +2 = B4");
    }

    #[test]
    fn audio_drive_amp_tracks_loudness() {
        // Silence → the floor; louder → up to the [0,4] ceiling.
        assert!((audio_drive_amp(0.1, 1.0, 0.0) - 0.1).abs() < 1e-6, "silence = floor");
        assert!((audio_drive_amp(0.1, 1.0, 0.5) - 0.6).abs() < 1e-6, "floor + amount·rms");
        assert_eq!(audio_drive_amp(0.1, 1.0, 100.0), 4.0, "clamped to the ceiling");
        assert!(audio_drive_amp(0.1, 1.0, 0.5) > audio_drive_amp(0.1, 1.0, 0.2), "monotone in rms");
    }

    #[test]
    fn lattice_freq_layouts() {
        let f0 = 110.0;
        // index 0 = f0 for every layout at B = 0 (the stiff-string fundamental is
        // itself slightly sharp when B > 0, which is physically correct).
        for layout in 0..4 {
            assert!((lattice_freq(layout, f0, 0, 0.5, 0.0) - f0).abs() < 1e-3, "layout {layout} idx0 = f0");
        }
        // Stretched fundamental (B > 0) is sharp of f0.
        assert!(lattice_freq(2, f0, 0, 0.0, 0.1) > f0, "stiff-string fundamental is sharp");
        // Octaves (spread 1): exact powers of two.
        assert!((lattice_freq(0, f0, 1, 1.0, 0.0) - 220.0).abs() < 1e-2, "octave +1");
        assert!((lattice_freq(0, f0, 3, 1.0, 0.0) - 880.0).abs() < 1e-1, "octave +3 = ×8");
        // Harmonic: integer multiples.
        assert!((lattice_freq(1, f0, 2, 0.0, 0.0) - 330.0).abs() < 1e-2, "harmonic n=3");
        // Stretched (B>0) rises ABOVE the harmonic partial.
        assert!(lattice_freq(2, f0, 4, 0.0, 0.01) > lattice_freq(1, f0, 4, 0.0, 0.0), "stretch sharpens");
        // Monotone increasing across the bank.
        let mut prev = 0.0;
        for i in 0..16 {
            let f = lattice_freq(0, f0, i, 0.25, 0.0);
            assert!(f >= prev, "octaves monotone");
            prev = f;
        }
    }

    #[test]
    fn ring_point_is_closed_and_deterministic() {
        let n = 64;
        // Index 0 and index n coincide (closed loop → seam-free scan).
        assert!((ring_point(0, n, 2.0) - ring_point(n, n, 2.0)).length() < 1e-4);
        // On the circle of radius r, in the XZ plane, deterministic.
        for i in 0..n {
            let p = ring_point(i, n, 2.0);
            assert!((p.length() - 2.0).abs() < 1e-4 && p.y.abs() < 1e-6);
            assert_eq!(p, ring_point(i, n, 2.0));
        }
    }

    #[test]
    fn hann_window_is_zero_at_edges_one_at_centre() {
        assert!(hann_window(0.0).abs() < 1e-6, "0 at start");
        assert!(hann_window(1.0).abs() < 1e-6, "0 at end");
        assert!((hann_window(0.5) - 1.0).abs() < 1e-6, "1 at centre");
        assert!(hann_window(0.25) > 0.0 && hann_window(0.25) < 1.0, "rises in between");
    }

    #[test]
    fn rect_mode_ratios_are_the_cube_eigenmodes() {
        let mut r = [0.0f32; 6];
        rect_mode_ratios(&mut r);
        // 1, √2, √3, 2, √5, √6 — inharmonic, ascending.
        let expect = [1.0, 2f32.sqrt(), 3f32.sqrt(), 2.0, 5f32.sqrt(), 6f32.sqrt()];
        for (i, (&g, &e)) in r.iter().zip(expect.iter()).enumerate() {
            assert!((g - e).abs() < 1e-4, "ratio {i}: got {g}, want {e}");
        }
        for w in r.windows(2) {
            assert!(w[1] >= w[0], "ascending");
        }
    }

    #[test]
    fn resolve_bpm_honors_the_source() {
        // Manual: always the dial, even when a host tempo is present.
        assert_eq!(resolve_bpm(2, 100.0, 120.0, true, 128.0), 100.0);
        // Host: follows the host tempo whenever the host provides one (independent
        // of the PLL-lock toggle); falls back to the dial when there's no host.
        assert_eq!(resolve_bpm(0, 100.0, 120.0, true, 0.0), 120.0);
        assert_eq!(resolve_bpm(0, 100.0, 0.0, false, 0.0), 100.0);
        // Audio: the detected BPM if locked, else the dial.
        assert_eq!(resolve_bpm(1, 100.0, 120.0, true, 128.0), 128.0);
        assert_eq!(resolve_bpm(1, 100.0, 120.0, true, 0.0), 100.0);
    }

    #[test]
    fn t60_pole_decays_by_60db_over_t60() {
        let sr = 48_000.0;
        let t60 = 0.5;
        let r = t60_to_r(t60, sr);
        assert!(r < 1.0, "no self-oscillation");
        // r^(t60·sr) should be 10^-3 (−60 dB).
        let decayed = r.powf(t60 * sr);
        assert!((decayed - 0.001).abs() < 1e-4, "−60 dB over T60 (got {decayed})");
    }

    #[test]
    fn fib_sphere_nodes_are_unit_and_deterministic() {
        for i in 0..64 {
            let p = fib_sphere_node(i, 64);
            assert!((p.length() - 1.0).abs() < 1e-4, "node {i} on the unit sphere");
            assert_eq!(p, fib_sphere_node(i, 64), "deterministic");
        }
        // Distinct patches: consecutive nodes differ.
        assert!(fib_sphere_node(0, 64) != fib_sphere_node(1, 64));
    }

    #[test]
    fn visual_lens_pivot_is_a_fixed_point() {
        // At f_audio = pivot the lens returns the anchors exactly (renders "at scale").
        let (rate, k) = visual_lens(220.0, 220.0, 1.5, 0.5, 3.0, 0.7, 0);
        assert!((rate - 1.5).abs() < 1e-5, "rate anchor at pivot");
        assert!((k - 3.0).abs() < 1e-5, "k anchor at pivot");
    }

    #[test]
    fn visual_lens_slope_endpoints() {
        // slope = 0 → constant rate for any pitch.
        let (r_lo, _) = visual_lens(110.0, 220.0, 2.0, 0.0, 3.0, 0.0, 0);
        let (r_hi, _) = visual_lens(3520.0, 220.0, 2.0, 0.0, 3.0, 0.0, 0);
        assert!((r_lo - 2.0).abs() < 1e-5 && (r_hi - 2.0).abs() < 1e-5, "slope 0 constant");
        // slope = 1 → strictly proportional (stay under the 4 Hz ceiling).
        let (r, _) = visual_lens(200.0, 100.0, 0.5, 1.0, 1.0, 1.0, 0);
        assert!((r - 1.0).abs() < 1e-4, "slope 1 proportional (0.5·200/100)");
    }

    #[test]
    fn visual_lens_is_monotonic_across_the_keyboard() {
        // Higher notes must always render at least as fast (order preserved), even
        // through the ceiling clamp.
        let mut prev = -1.0;
        let mut f = 27.5; // A0
        while f <= 14080.0 {
            let (rate, _) = visual_lens(f, 220.0, 0.4, 0.34, 4.0, 0.34, 0);
            assert!(rate >= prev - 1e-6, "rate non-decreasing at {f} Hz");
            prev = rate;
            f *= 2f32.powf(1.0 / 12.0);
        }
    }

    #[test]
    fn visual_lens_octave_lock_snaps_to_powers_of_two() {
        for &f in &[55.0f32, 110.0, 130.81, 220.0, 440.0, 1000.0] {
            let (rate, _) = visual_lens(f, 220.0, 1.0, 0.5, 3.0, 0.5, 1);
            // rate / anchor(1.0) must be an exact power of two (integer log2).
            let l2 = (rate / 1.0).log2();
            assert!((l2 - l2.round()).abs() < 1e-4, "octave-locked rate is 2ⁿ at {f} Hz (got {rate})");
        }
    }

    #[test]
    fn visual_lens_respects_the_photosensitivity_ceiling() {
        // A fast note under a steep slope must be clamped to the engine ceiling.
        let (rate, _) = visual_lens(14000.0, 220.0, 1.0, 1.0, 3.0, 1.0, 0);
        assert!((rate - VIS_RATE_CEILING).abs() < 1e-4, "clamped to the ceiling");
        // Even octave-lock cannot defeat it.
        let (rate2, _) = visual_lens(14000.0, 220.0, 1.0, 1.0, 3.0, 1.0, 1);
        assert!(rate2 <= VIS_RATE_CEILING + 1e-4, "octave-lock still under ceiling");
    }

    #[test]
    fn maxwell_axial_e_is_signed_and_oscillates() {
        // A +Z dipole at the origin; sample off-axis so E·Z is non-zero. The
        // projection must swing sign as the phase advances by π (a real tone, not
        // a rectified |E|).
        let src = [MaxSource { pos: Vec3::ZERO, q: 1.0, phase: 0.0 }];
        let p = Vec3::new(1.0, 0.0, 0.5);
        let (k, near, r_min) = (1.0, 0.2, 0.1);
        let a = maxwell_axial_e(p, &src, true, Vec3::Z, k, near, r_min, 0.3);
        let b = maxwell_axial_e(p, &src, true, Vec3::Z, k, near, r_min, 0.3 + std::f32::consts::PI);
        assert!(a.abs() > 1e-4, "non-zero off-axis E·Z");
        assert!(a * b < 0.0, "E·Z flips sign over a half cycle (a signed tone)");
    }

    #[test]
    fn acoustic_field_is_retarded_and_harmonic() {
        // The field depends on time only through arg = phase − k·r. The pressure
        // node (arg=0) rides outward: at radius r it appears at phase = k·r, and
        // at a larger radius at the correspondingly later phase — that k·r lag is
        // the retardation. Also 2π-periodic in phase (harmonic).
        let src = acoustic_sources(AcousticKind::Monopole, 1.0);
        let (k, near, r_min) = (1.1, 0.6, 0.1);
        for r in [2.0f32, 3.5, 5.0] {
            let (pn, _) = acoustic_field_pu(Vec3::new(0.0, r, 0.0), &src, k, near, r_min, k * r);
            assert!(pn.abs() < 1e-5, "retarded node at phase = k·r");
        }
        let pt = Vec3::new(1.0, 2.0, -1.0);
        let (a, _) = acoustic_field_pu(pt, &src, k, near, r_min, 0.3);
        let (b, _) = acoustic_field_pu(pt, &src, k, near, r_min, 0.3 + std::f32::consts::TAU);
        assert!((a - b).abs() < 1e-4, "harmonic (2π-periodic in phase)");
    }

    #[test]
    fn acoustic_energy_is_nonnegative_and_finite() {
        let src = acoustic_sources(AcousticKind::LongitudinalQuad, 1.2);
        for &phase in &[0.0f32, 0.9, 2.1, 5.0] {
            for &p in &[
                Vec3::ZERO,
                Vec3::new(2.0, 1.0, -1.0),
                Vec3::new(0.0, 0.0, 0.5),
                Vec3::new(-3.0, 4.0, 2.0),
            ] {
                for &blend in &[0.0f32, 0.5, 1.0] {
                    let w = acoustic_energy_density(p, &src, blend, 1.0, 0.5, 0.15, phase);
                    assert!(w.is_finite() && w >= 0.0, "energy finite & ≥ 0");
                }
            }
        }
    }

    #[test]
    fn acoustic_lattice_is_grid_and_deterministic() {
        let src = acoustic_sources(AcousticKind::Dipole, 1.0);
        let mut a = Strands::new();
        let mut b = Strands::new();
        let topo = acoustic_lattice_strands(
            5, 8, 6, 6.0, 180.0, &src, 0.0, false, 1.0, 0.5, 1.0, 0.1, 0.05, 0.3, 0, 0.0, &mut a,
        );
        acoustic_lattice_strands(
            5, 8, 6, 6.0, 180.0, &src, 0.0, false, 1.0, 0.5, 1.0, 0.1, 0.05, 0.3, 0, 0.0, &mut b,
        );
        assert_eq!(topo, Topology::Grid);
        assert_eq!(a.len(), 5 * 8);
        assert_eq!(a[0].len(), 6);
        for (sa, sb) in a.iter().zip(b.iter()) {
            for (fa, fb) in sa.iter().zip(sb.iter()) {
                assert!(fa.position.is_finite());
                assert_eq!(fa.position, fb.position);
            }
        }
    }

    #[test]
    fn acoustic_aura_field_direction_and_energy_blend() {
        // The AnalyticField::Acoustic consumer: velocity() is a unit direction and
        // drive-invariant; energy() scales by drive².
        let src = acoustic_sources(AcousticKind::Dipole, 1.0);
        let field = AnalyticField::Acoustic {
            sources: src.clone(),
            blend: 1.0, // pure circulation channel
            k: 1.0,
            near: 0.5,
            r_min: 0.1,
            phase: 0.6,
            drive: 1.0,
            intensity: 0.0,
        };
        let p = Vec3::new(1.5, 2.0, 0.5);
        let v = field.velocity(p);
        assert!((v.length() - 1.0).abs() < 1e-4 || v.length() < 1e-6, "velocity is unit (or zero)");
        let e1 = field.energy(p);
        let field2 = AnalyticField::Acoustic {
            sources: src,
            blend: 1.0,
            k: 1.0,
            near: 0.5,
            r_min: 0.1,
            phase: 0.6,
            drive: 2.0,
            intensity: 0.0,
        };
        let e2 = field2.energy(p);
        assert!(e1 >= 0.0 && e2 >= 0.0);
        assert!((e2 - 4.0 * e1).abs() < 1e-3 * (1.0 + e2), "energy scales by drive²");
    }

    #[test]
    fn acoustic_circulation_is_transverse_and_in_quadrature() {
        // The dual-field companion (#325): the circulation must be orthogonal to the
        // radial (transverse, azimuthal about +Z) and 90° out of phase with the
        // pressure (peaks where the pressure crosses zero), so the crossfade is a true
        // dual — not a re-scan of one field.
        let src = acoustic_sources(AcousticKind::Monopole, 1.0);
        let (k, r_min) = (1.5f32, 0.1f32);
        // An off-axis point (not on +Z, where the azimuthal ring vanishes).
        let p = Vec3::new(2.0, 0.5, 1.0);
        let axis = Vec3::Z;
        // Transverse: c ⟂ the radial from the source, and c ⟂ the axis (azimuthal).
        let phase = 0.7;
        let c = acoustic_circulation(p, &src, axis, 1.0, k, r_min, phase);
        let rhat = (p - src[0].pos).normalize();
        assert!(c.length() > 1e-4, "off-axis circulation is non-zero");
        assert!(c.dot(rhat).abs() < 1e-4, "circulation ⟂ radial (transverse)");
        assert!(c.dot(axis).abs() < 1e-4, "circulation ⟂ axis (azimuthal)");
        // Quadrature: where the pressure is maximal (sin arg = ±1), the circulation
        // (cos arg) is ~zero, and vice-versa. Pick the phase that maximises pressure.
        let r = (p - src[0].pos).length().max(r_min);
        let phase_pmax = std::f32::consts::FRAC_PI_2 + k * r; // sin(phase - kr) = 1
        let (pres, _u) = acoustic_field_pu(p, &src, k, 0.5, r_min, phase_pmax);
        let c_at_pmax = acoustic_circulation(p, &src, axis, 1.0, k, r_min, phase_pmax);
        assert!(pres.abs() > 0.1, "pressure near its peak");
        assert!(c_at_pmax.length() < 1e-3, "circulation ~0 when pressure peaks (quadrature)");
    }

    // --- Acoustic Tier 4 (#325): cavity modes + intensity flux ---

    #[test]
    fn cavity_pressure_has_nodal_planes() {
        // A (2,1,1) mode in a box of half-extent 4: the x-pressure factor cos(kx·x)
        // with kx = 2π/4 = π/2 has a nodal plane at x = 1 (kx·x = π/2). Pick a phase
        // with cos(ωt) ≠ 0 so the temporal factor doesn't hide it.
        let dims = Vec3::splat(4.0);
        let modes = Vec3::new(2.0, 1.0, 1.0);
        let (p_node, _) = cavity_field_pu(Vec3::new(1.0, 0.3, 0.2), modes, dims, 0.0);
        assert!(p_node.abs() < 1e-5, "pressure vanishes on the x nodal plane");
        let (p_anti, _) = cavity_field_pu(Vec3::new(0.0, 0.0, 0.0), modes, dims, 0.0);
        assert!(p_anti.abs() > 0.5, "pressure antinode at the centre");
    }

    #[test]
    fn cavity_velocity_is_temporal_quadrature_of_pressure() {
        // p ∝ cos(ωt), u ∝ sin(ωt): 90° out of temporal phase. At ωt=0 the velocity
        // vanishes (pressure max); at ωt=π/2 the pressure vanishes (velocity max).
        let dims = Vec3::splat(5.0);
        let modes = Vec3::new(1.0, 2.0, 1.0);
        let p = Vec3::new(0.7, -0.4, 0.9);
        let (pr0, u0) = cavity_field_pu(p, modes, dims, 0.0);
        assert!(pr0.abs() > 1e-3 && u0.length() < 1e-5, "ωt=0: pressure max, velocity null");
        let (pr1, u1) = cavity_field_pu(p, modes, dims, std::f32::consts::FRAC_PI_2);
        assert!(pr1.abs() < 1e-5 && u1.length() > 1e-3, "ωt=π/2: pressure null, velocity max");
    }

    #[test]
    fn cavity_modes_walk_on_the_beat() {
        let base = Vec3::new(2.0, 2.0, 1.0);
        // morph 0 → always the base modes.
        for b in 0..8 {
            assert_eq!(cavity_morph_modes(base, b, 0.0), base);
        }
        // morph > 0 → beat 0 is the base, later beats change (deterministically).
        assert_eq!(cavity_morph_modes(base, 0, 0.5), base);
        let m1 = cavity_morph_modes(base, 1, 0.5);
        assert!(m1 != base, "the mode advances on the next beat");
        assert_eq!(m1, cavity_morph_modes(base, 1, 0.5), "deterministic");
        // #325 T5: the walk is now 3-D — after enough beats the z mode advances too.
        let span = (1.0_f32 + 0.5 * 4.0).round() as u32; // 3
        let period = span + 1; // 4
        let mz = cavity_morph_modes(base, period * period, 0.5);
        assert!(mz.z > base.z, "z mode walks after period² beats (3-D reorganisation)");
    }

    // ---- #391 Tier 1: quantitative instrumentation --------------------------

    fn probe_dipole_field(phase: f32) -> AnalyticField {
        AnalyticField::Maxwell {
            sources: vec![MaxSource { pos: Vec3::ZERO, q: 1.0, phase: 0.0 }],
            dipoles: true,
            blend: 0.0,
            k: 1.0,
            near: 1.0,
            r_min: 0.05,
            phase,
            antenna_len: 1.0,
            antenna_segs: 0,
            drive: 1.0,
            offset: Vec3::ZERO,
        }
    }

    #[test]
    fn probe_em_matches_the_field_kernels_and_poynting() {
        let field = probe_dipole_field(0.3);
        let p = Vec3::new(1.3, 0.7, -0.9);
        let pr = field.probe(p);
        assert_eq!(pr.kind, ProbeKind::Em);
        // The probe reads the SAME kernel the visual draws.
        let (e, b) = maxwell_field_eb(p, &[MaxSource { pos: Vec3::ZERO, q: 1.0, phase: 0.0 }], true, 1.0, 1.0, 0.05, 0.3);
        assert!((pr.primary - e).length() < 1e-6, "E mismatch");
        assert!((pr.secondary - b).length() < 1e-6, "B mismatch");
        // Energy split = ½|E|², ½|B|²; flux = E×B, ⟂ both.
        assert!((pr.energy_a - 0.5 * e.length_squared()).abs() < 1e-6);
        assert!((pr.energy_b - 0.5 * b.length_squared()).abs() < 1e-6);
        assert!(pr.flux.dot(e).abs() < 1e-4 && pr.flux.dot(b).abs() < 1e-4, "Poynting ⟂ E and B");
        // The probe's energy_total is the same quantity the aura glows by (blend 0.5).
        let glow = field.energy(p); // blend 0 → ½·? actually energy() uses the field's blend
        assert!(glow.is_finite());
    }

    #[test]
    fn probe_drive_scales_energy_quadratically() {
        let mut f1 = probe_dipole_field(0.5);
        let p = Vec3::new(0.8, -0.2, 1.1);
        let e1 = f1.probe(p).energy_total();
        if let AnalyticField::Maxwell { drive, .. } = &mut f1 {
            *drive = 3.0;
        }
        let e3 = f1.probe(p).energy_total();
        assert!((e3 / e1 - 9.0).abs() < 1e-3, "energy ∝ drive²: {} vs {}", e3, e1);
    }

    #[test]
    fn probe_acoustic_carries_pressure_velocity_and_intensity() {
        let field = AnalyticField::Acoustic {
            sources: vec![MaxSource { pos: Vec3::ZERO, q: 1.0, phase: 0.0 }],
            blend: 0.0,
            k: 1.0,
            near: 0.5,
            r_min: 0.05,
            phase: 0.4,
            drive: 1.0,
            intensity: 0.0,
        };
        let p = Vec3::new(1.1, 0.3, -0.6);
        let pr = field.probe(p);
        assert_eq!(pr.kind, ProbeKind::Acoustic);
        let (pres, u) = acoustic_field_pu(p, &[MaxSource { pos: Vec3::ZERO, q: 1.0, phase: 0.0 }], 1.0, 0.5, 0.05, 0.4);
        assert!((pr.scalar - pres).abs() < 1e-6, "pressure mismatch");
        assert!((pr.secondary - u).length() < 1e-6, "velocity mismatch");
        assert!((pr.flux - acoustic_intensity(pres, u)).length() < 1e-6, "intensity I = p·u");
        assert!((pr.energy_a - 0.5 * pres * pres).abs() < 1e-6);
    }

    #[test]
    fn probe_acoustic_intensity_mode_tracks_the_energization() {
        // With intensity > 0 the visual advects along Î and glows by |p·u|·intensity,
        // so the probe must report that (not ½p²/½|u|²) — else the ledger disagrees with
        // the drawn field.
        let mk = |intensity: f32| AnalyticField::Acoustic {
            sources: vec![MaxSource { pos: Vec3::ZERO, q: 1.0, phase: 0.0 }],
            blend: 0.0,
            k: 1.0,
            near: 0.5,
            r_min: 0.05,
            phase: 0.4,
            drive: 1.3,
            intensity,
        };
        let p = Vec3::new(1.1, 0.3, -0.6);
        let field = mk(2.0);
        let pr = field.probe(p);
        assert_eq!(pr.energy_a, 0.0, "flux mode puts all energy in the flux channel");
        // The probe's total energy equals the visual's own energization (number = picture).
        assert!(
            (pr.energy_total() - field.energy(p)).abs() < 1e-4,
            "intensity energization: probe {} vs drawn {}",
            pr.energy_total(),
            field.energy(p)
        );
        // The reported flux is the scaled intensity vector |p·u|·intensity.
        assert!((pr.flux.length() - pr.energy_b).abs() < 1e-5);
        // intensity = 0 falls back to the physical density split.
        let pr0 = mk(0.0).probe(p);
        assert!(pr0.energy_a > 0.0 && pr0.energy_b > 0.0);
    }

