    fn probe_non_field_generator_is_zero() {
        let pr = AnalyticField::CurlNoise { scale: 1.0, t: 0.0, bound: 0.0, seed: 1 }.probe(Vec3::ONE);
        assert_eq!(pr.kind, ProbeKind::Em);
        assert_eq!(pr.energy_total(), 0.0);
        assert_eq!(pr.flux, Vec3::ZERO);
    }

