        let led = field_energy_ledger(&field, Vec3::ZERO, 2.0, 8);
        assert!(led.total > 0.0, "a driven dipole carries energy");
        assert!((led.u_a + led.u_b - led.total).abs() < 1e-3 * led.total.max(1.0));
        assert!((0.0..=1.0).contains(&led.balance), "balance is a fraction: {}", led.balance);
        assert_eq!(led.samples, 8 * 8 * 8);
        assert!(led.net_flux.is_finite());
