    #[test]
    fn energy_ledger_trades_between_channels_over_a_cycle() {
        // As the dipole oscillates the E/B split shifts (the ledger's whole point).
        let a = field_energy_ledger(&probe_dipole_field(0.0), Vec3::ZERO, 2.0, 8);
        let b = field_energy_ledger(&probe_dipole_field(std::f32::consts::FRAC_PI_2), Vec3::ZERO, 2.0, 8);
        assert!((a.balance - b.balance).abs() > 1e-3, "the E↔B balance moves over the cycle");
    }

    #[test]
    fn poynting_flux_zero_normal_and_sign_flip() {
        let field = probe_dipole_field(0.2);
        // Degenerate normal → 0 (no crash).
        assert_eq!(poynting_flux_through_plane(&field, Vec3::ONE, Vec3::ZERO, 1.0, 8), 0.0);
        // Flipping the normal flips the sign of the flux through the same patch.
        let c = Vec3::new(1.5, 0.0, 0.0);
        let f_pos = poynting_flux_through_plane(&field, c, Vec3::X, 1.0, 12);
        let f_neg = poynting_flux_through_plane(&field, c, Vec3::NEG_X, 1.0, 12);
        assert!((f_pos + f_neg).abs() < 1e-4, "reversing n̂ negates the flux: {f_pos} vs {f_neg}");
    }

