    #[test]
    fn acoustic_cavity_aura_variant_and_intensity() {
        let modes = Vec3::new(2.0, 2.0, 1.0);
        let dims = Vec3::splat(6.0);
        let p = Vec3::new(1.3, 0.7, 0.9);
        // Blend mode: unit velocity, energy ≥ 0 scaling by drive².
        let f1 = AnalyticField::AcousticCavity { modes, dims, blend: 1.0, phase: 0.6, drive: 1.0, intensity: 0.0 };
        let v = f1.velocity(p);
        assert!((v.length() - 1.0).abs() < 1e-4 || v.length() < 1e-6, "unit (or zero) velocity");
        let e1 = f1.energy(p);
        let f2 = AnalyticField::AcousticCavity { modes, dims, blend: 1.0, phase: 0.6, drive: 2.0, intensity: 0.0 };
        assert!((f2.energy(p) - 4.0 * e1).abs() < 1e-3 * (1.0 + e1), "energy scales by drive²");
        // Intensity mode: velocity is the (unit) energy-flux direction.
        let fi = AnalyticField::AcousticCavity { modes, dims, blend: 0.0, phase: 0.6, drive: 1.0, intensity: 1.0 };
        let vi = fi.velocity(p);
        assert!((vi.length() - 1.0).abs() < 1e-4 || vi.length() < 1e-6, "intensity dir is unit");
    }

