    #[test]
    fn mandelbulb_de_is_signed_and_finite() {
        // Deep inside the bulb the estimate is ≤ 0 (the centre is in the set);
        // well outside it is positive; both are finite for the default power-8.
        let (d_in, trap_in) = mandelbulb_de(Vec3::ZERO, 8.0, 8, 2.0, 0.0);
        assert!(d_in.is_finite(), "inside DE not finite: {d_in}");
        assert!(d_in <= 0.0, "centre should be inside the set: {d_in}");
        assert!(trap_in <= 2.0);

        let far = Vec3::new(3.0, 0.0, 0.0);
        let (d_out, _) = mandelbulb_de(far, 8.0, 8, 2.0, 0.0);
        assert!(d_out.is_finite() && d_out > 0.0, "outside DE should be +ve: {d_out}");
        // The estimate must not over-shoot the true distance to a radius-≈1.2
        // surface (a valid DE is a lower bound on the real distance).
        assert!(d_out <= far.length(), "DE over-estimates distance: {d_out}");
    }

    #[test]
    fn mandelbulb_de_radial_monotonic_outside() {
        // Marching outward along +X, the distance estimate should keep growing
        // once we're clear of the surface — a sane sphere-tracing field.
        let p = |x: f32| mandelbulb_de(Vec3::new(x, 0.0, 0.0), 8.0, 8, 2.0, 0.0).0;
        let (a, b, c) = (p(1.6), p(2.4), p(3.2));
        assert!(a.is_finite() && b.is_finite() && c.is_finite());
        assert!(b > a && c > b, "DE not increasing outward: {a} {b} {c}");
    }

    #[test]
    fn smin_h_matches_polynomial_identity() {
        // The blended distance from creature_map's inline smin must equal IQ's
        // closed form mix(b,a,h) − k·h·(1−h), and reduce to min() as k → 0.
        let prims = [
            CreaturePrim::ellipsoid(Vec3::new(-0.4, 0.0, 0.0), Vec3::splat(0.5), 0.0, 0.0),
            CreaturePrim::ellipsoid(Vec3::new(0.4, 0.0, 0.0), Vec3::splat(0.5), 0.3, 0.0),
        ];
        let p = Vec3::new(0.0, 0.2, 0.0);
        let a = sd_ellipsoid(p - prims[0].a, prims[0].b);
        let b = sd_ellipsoid(p - prims[1].a, prims[1].b);
        let k = 0.3_f32;
        let h = (0.5 + 0.5 * (b - a) / k).clamp(0.0, 1.0);
        let expect = (b * (1.0 - h) + a * h) - k * h * (1.0 - h);
        assert!((creature_sdf(&prims, p) - expect).abs() < 1e-6);
        // The blend never exceeds either input's plain min (smin ≤ min).
        assert!(creature_sdf(&prims, p) <= a.min(b) + 1e-6);
    }

    #[test]
    fn creature_map_signed_inside_outside_and_glow_blends() {
        // Two overlapping spheres: a point at the centre of one is inside (d<0);
        // a point far away is outside (d>0). Glow stays within the primitives'
        // range everywhere (a convex blend of endpoint glows).
        let prims = [
            CreaturePrim::ellipsoid(Vec3::new(-0.3, 0.0, 0.0), Vec3::splat(0.5), 0.2, 0.1),
            CreaturePrim::ellipsoid(Vec3::new(0.3, 0.0, 0.0), Vec3::splat(0.5), 0.2, 1.0),
        ];
        let (d_in, g_in) = creature_map(&prims, Vec3::new(0.3, 0.0, 0.0));
        assert!(d_in < 0.0, "inside a sphere should be negative: {d_in}");
        assert!((0.1..=1.0).contains(&g_in), "glow out of range: {g_in}");
        let (d_out, _) = creature_map(&prims, Vec3::new(3.0, 0.0, 0.0));
        assert!(d_out > 0.0 && d_out.is_finite(), "outside should be +ve finite: {d_out}");
    }

    #[test]
    fn round_cone_is_signed_and_capsule_like() {
        // On the axis midpoint of a uniform-radius round cone (= a capsule) the
        // distance is −r; a point r+δ off-axis is just outside.
        let a = Vec3::new(0.0, 0.0, -0.5);
        let b = Vec3::new(0.0, 0.0, 0.5);
        let r = 0.2_f32;
        let mid = Vec3::ZERO;
        assert!((sd_round_cone(mid, a, b, r, r) + r).abs() < 1e-3);
        let off = Vec3::new(r + 0.05, 0.0, 0.0);
        assert!(sd_round_cone(off, a, b, r, r) > 0.0);
    }

    #[test]
    fn body_plans_are_bounded_finite_and_deterministic() {
        for form in 0..CREATURE_FORMS {
            let plan = creature_body_plan(form);
            assert!(!plan.is_empty(), "form {form} empty");
            assert!(plan.len() <= CREATURE_MAX_PRIMS, "form {form} exceeds prim cap");
            let radius = creature_bounds(&plan);
            assert!(radius.is_finite() && radius > 0.0);
            // Every primitive's centre lies inside the bounding sphere, and the
            // field is finite across a grid spanning the bound.
            for pr in &plan {
                assert!(pr.a.length() <= radius + 1e-3, "prim outside bound in form {form}");
            }
            for gz in -2..=2 {
                for gy in -2..=2 {
                    for gx in -2..=2 {
                        let p = Vec3::new(gx as f32, gy as f32, gz as f32) * (radius * 0.5);
                        let (d, g) = creature_map(&plan, p);
                        assert!(d.is_finite() && g.is_finite(), "non-finite field form {form}");
                    }
                }
            }
            // Determinism: rebuilding the plan yields identical primitives.
            let again = creature_body_plan(form);
            assert_eq!(plan.len(), again.len());
            let p = Vec3::new(0.1, 0.15, 0.2);
            assert_eq!(creature_sdf(&plan, p), creature_sdf(&again, p));
        }
    }

    #[test]
    fn creature_warp_is_identity_at_zero_amplitude() {
        let p = Vec3::new(0.3, -0.2, 0.7);
        assert_eq!(creature_warp(p, 1.0, 4.0, 0.0), p);
        // A non-zero warp only displaces X (the lateral undulation axis).
        let w = creature_warp(p, 0.0, 2.0, 0.1);
        assert!((w.y - p.y).abs() < 1e-9 && (w.z - p.z).abs() < 1e-9);
        assert!((w.x - p.x).abs() > 0.0);
    }

    #[test]
    fn metachronal_wave_is_a_rectified_sharpened_band() {
        // Range is [0,1]: 1 at a crest (freq·s − phase = π/2), 0 through the whole
        // negative half of the sine.
        let crest = metachronal_wave(std::f32::consts::FRAC_PI_2, 0.0, 1.0, 1.0);
        assert!((crest - 1.0).abs() < 1e-5, "crest not 1: {crest}");
        // A point in the sine's negative half rectifies to exactly 0.
        assert_eq!(metachronal_wave(-std::f32::consts::FRAC_PI_2, 0.0, 1.0, 4.0), 0.0);
        // Sharpening narrows the band: at a partial-crest sample, higher `sharp`
        // gives a smaller value (x^n shrinks for 0<x<1 as n grows), never above 1.
        let s = 0.6_f32; // sin(0.6) ≈ 0.5646, in (0,1)
        let soft = metachronal_wave(s, 0.0, 1.0, 1.0);
        let tight = metachronal_wave(s, 0.0, 1.0, 6.0);
        assert!(tight < soft && tight >= 0.0 && soft <= 1.0);
        // The band travels with phase: at a fixed spine point, advancing the phase
        // changes the wave value (here s=1.2 is near the crest at phase 0 and in the
        // rectified-to-zero half at phase π/2).
        let a = metachronal_wave(1.2, 0.0, 1.0, 1.0);
        let b = metachronal_wave(1.2, std::f32::consts::FRAC_PI_2, 1.0, 1.0);
        assert!((a - b).abs() > 1e-3, "phase does not move the band: {a} {b}");
    }

    #[test]
    fn prim_spine_coord_tracks_position_along_z() {
        // A centred primitive reports its centre z; a cone reports its midpoint.
        let e = CreaturePrim::ellipsoid(Vec3::new(0.1, 0.2, 0.7), Vec3::splat(0.3), 0.1, 0.0);
        assert!((prim_spine_coord(&e) - 0.7).abs() < 1e-6);
        let c = CreaturePrim::cone(Vec3::new(0.0, 0.0, -0.4), Vec3::new(0.0, 0.0, 0.8), 0.05, 0.02, 0.03, 1.0);
        assert!((prim_spine_coord(&c) - 0.2).abs() < 1e-6);
    }

