    fn parse_creature_spec_expands_emitters_and_mirror() {
        // 1 ellipsoid + a chain of 4 + a mirrored cone = 1 + 4 + 2 = 7 primitives.
        let json = r#"{
            "name": "test beast",
            "emit": [
                {"kind":"ellipsoid","center":[0,0,-1],"radii":[0.2,0.2,0.2],"k":0.1,"glow":0.3},
                {"kind":"chain","of":"ellipsoid","count":4,"a":[0,0,-0.8],"b":[0,0,0.8],
                 "size0":[0.2,0.2,0.14],"size1":[0.05,0.05,0.14],"k":0.09,"glow":0.15},
                {"kind":"cone","a":[0.1,0,-1.1],"b":[0.3,0.1,-1.3],"r0":0.03,"r1":0.01,
                 "k":0.02,"glow":1.5,"mirror_x":true}
            ]
        }"#;
        let plan = parse_creature_spec(json).expect("valid spec");
        assert_eq!(plan.len(), 7, "emitter expansion count");
        // The mirrored cone's twin has a negated x on both endpoints.
        let last = plan[6];
        assert!((last.a.x + 0.1).abs() < 1e-6 && (last.b.x + 0.3).abs() < 1e-6);
        // The field is finite and bounded.
        let r = creature_bounds(&plan);
        assert!(r.is_finite() && r > 0.0);
        for gx in -2..=2 {
            let p = Vec3::new(gx as f32 * 0.4, 0.1, 0.2);
            assert!(creature_sdf(&plan, p).is_finite());
        }
    }

